using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public static class TestHelpers
{
    public static SchoolContext CreateInMemoryContext(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }

    public static void SeedStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { ID = 1, LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { ID = 3, LastName = "Anand", FirstMidName = "Arturo", EnrollmentDate = new DateTime(2021, 9, 1) }
        );
        context.SaveChanges();
    }

    public static void SeedDepartments(SchoolContext context)
    {
        context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "English", Budget = 100000, StartDate = new DateTime(2010, 1, 1) },
            new Department { DepartmentID = 2, Name = "Mathematics", Budget = 200000, StartDate = new DateTime(2012, 1, 1) }
        );
        context.SaveChanges();
    }

    public static void SeedCourses(SchoolContext context)
    {
        SeedDepartments(context);
        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2 }
        );
        context.SaveChanges();
    }

    public static void SeedInstructors(SchoolContext context)
    {
        context.Instructors.AddRange(
            new Instructor
            {
                ID = 10, LastName = "Zheng", FirstMidName = "Roger", HireDate = new DateTime(2004, 2, 12),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
            },
            new Instructor
            {
                ID = 11, LastName = "Kapoor", FirstMidName = "Candace", HireDate = new DateTime(2001, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            }
        );
        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain any leftover messages from static queue
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose() => _service.Dispose();

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Student 'John Doe' has been created")]
    [InlineData(EntityOperation.UPDATE, "Student 'John Doe' has been updated")]
    [InlineData(EntityOperation.DELETE, "Student 'John Doe' has been deleted")]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage(EntityOperation op, string expectedMessage)
    {
        _service.SendNotification("Student", "1", "John Doe", op, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal(op.ToString(), notification.Operation);
        Assert.Equal(expectedMessage, notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Student (ID: 42) has been created")]
    [InlineData(EntityOperation.UPDATE, "Student (ID: 42) has been updated")]
    [InlineData(EntityOperation.DELETE, "Student (ID: 42) has been deleted")]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage(EntityOperation op, string expectedMessage)
    {
        _service.SendNotification("Student", "42", null, op, "TestUser");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        _service.SendNotification("Course", "101", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _service.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void SendNotification_MultipleMessages_ReceivedInOrder()
    {
        _service.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToApproximateNow()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _service.SendNotification("Test", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _service.ReceiveNotification();

        Assert.InRange(notification!.CreatedAt, before, after);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation but should not throw
        var ex = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_Works()
    {
        _service.SendNotification("Dept", "5", EntityOperation.DELETE, "User1");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("Dept (ID: 5)", notification.Message);
        Assert.Equal("User1", notification.CreatedBy);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(21, result[0]);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Theory]
    [InlineData(10, 10, 1)]
    [InlineData(11, 10, 2)]
    [InlineData(0, 10, 0)]
    [InlineData(1, 1, 1)]
    public void TotalPages_CalculatedCorrectly(int totalItems, int pageSize, int expectedPages)
    {
        var source = Enumerable.Range(1, Math.Max(totalItems, 0)).AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, pageSize);

        Assert.Equal(expectedPages, result.TotalPages);
    }
}

