using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        TestHelpers.SeedCourses(_context);
        TestHelpers.SeedInstructors(_context);

        // Add course assignments
        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 1050 });
        _context.SaveChanges();

        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_NoParameters_ReturnsViewWithInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_ShowsCourses()
    {
        var result = _controller.Index(10, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Chemistry", model.Courses.First().Title);
    }

    [Fact]
    public void Details_ValidId_ReturnsInstructor()
    {
        var result = _controller.Details(10) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Zheng", instructor.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithCourseData()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInstructor",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Instructors.Count());
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        var instructor = new Instructor
        {
            LastName = "CourseInstructor",
            FirstMidName = "Multi",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, new[] { "1050", "4022" }) as RedirectToActionResult;

        Assert.NotNull(result);
        var saved = _context.Instructors.First(i => i.LastName == "CourseInstructor");
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor { CourseAssignments = new List<CourseAssignment>() };

        var result = _controller.Create(instructor, null) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsInstructor()
    {
        var result = _controller.Edit((int?)10) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Zheng", instructor.LastName);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsInstructor()
    {
        var result = _controller.Delete(10) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Zheng", instructor.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndRedirects()
    {
        var result = _controller.DeleteConfirmed(11) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Instructors);
    }

    [Fact]
    public void DeleteConfirmed_ClearsDepartmentAdministrator()
    {
        // Assign instructor 10 as administrator of department 1
        var dept = _context.Departments.Find(1)!;
        dept.InstructorID = 10;
        _context.SaveChanges();

        _controller.DeleteConfirmed(10);

        var updatedDept = _context.Departments.Find(1)!;
        Assert.Null(updatedDept.InstructorID);
    }
}

